  dd.innerHTML=ddLista.length?ddLista.map((m,j)=>(m.t!==ed?(ed=m.t,`<div class="g">${esc(m.t||'Muut')}</div>`):'')+`<div class="o ${j===ddIdx?'act':''}" data-i="${j}">${esc(matNimi(m))}<span>${matHinta(m)}</span></div>`).join(''):'<div class="o">Ei osumia – lisää oma materiaali</div>';
  dd.hidden=false; const act=dd.querySelector('.act'); if(act) act.scrollIntoView({block:'nearest'}); }
function valitse(r,m){ const vaihtui=r.mat!==m; r.mat=m; if(!mitallinen(m)) r.tila='maara'; else if(!r.tila) r.tila='mitat'; r.osto=false; r.kokolevyt=false; if(vaihtui) r.nayta=!PIILO.includes(m.t);

  piirra(r.id,'.r2 input.n'); muuttui(true); }
function lisaa(tyyppi){ if(!D) return; const r={id:uid(),tyyppi,kaanna:true,nayta:true,vali:nS(D.asetukset.vali),kate:'',hukka:'',aikatila:'min',aika:'',kasin:true}; if(tyyppi==='vakio') r.maara='1'; if(tyyppi==='oma'||tyyppi==='vapaa'){ r.maara='1'; r.yks='kpl'; }
  sijoita(r); piirra(r.id,'.main input, .main select'); if(tyyppi!=='materiaali'&&tyyppi!=='kone'&&tyyppi!=='vakio') muuttui(); }

// ---------- tapahtumat ----------
document.addEventListener('input',e=>{ const t=e.target; if(t.id==='tarjous'){ S.tarjous=t.value; hintaDirty=true; laske(); muuttui(); return; }
  const r=t.dataset&&rivi(t.dataset.id); if(!r) return;
  if(t.dataset.combo){ t.dataset.haku=t.value; ddIdx=0; avaaDd(t); return; }
  if(t.dataset.kate!==undefined){ const v=num(t.value); r.kate=(v===null||v===Number(t.dataset.kate))?'':t.value; laske(); muuttui(); return; }
  if(t.dataset.k){ r[t.dataset.k]=t.value; laske(); muuttui(); } });
document.addEventListener('change',e=>{ const t=e.target, r=t.dataset&&rivi(t.dataset.id); if(!r) return;
  if(t.dataset.c){ r[t.dataset.c]=t.checked; laske(); muuttui(); }
  if(t.dataset.osto){ r.osto=t.value==='1'; laske(); muuttui(); }
  if(t.dataset.kone){ r.kone=D.koneBy[t.value]||null; piirra(r.id,'.r2 input.n'); muuttui(); }
  if(t.dataset.tuote){ r.tuote=D.tuoteBy[t.value]||null; if(!num(r.maara)) r.maara='1'; piirra(r.id,'.r2 input.n'); muuttui(); } });
document.addEventListener('focusin',e=>{ const t=e.target; if(t.dataset&&t.dataset.combo){ t.dataset.haku=''; t.select(); ddIdx=0; avaaDd(t); } });
document.addEventListener('focusout',e=>{ const t=e.target; if(t.dataset&&t.dataset.combo){ const id=t.dataset.id; setTimeout(()=>{ const r=rivi(id), dd=$('#dd-'+id); if(dd) dd.hidden=true; if(r&&document.activeElement!==t&&document.body.contains(t)) t.value=r.mat?matNimi(r.mat):''; },150); } });
document.addEventListener('mousedown',e=>{ const o=e.target.closest('.dd .o'); if(o&&o.dataset.i!==undefined){ e.preventDefault(); valitse(rivi(o.parentElement.id.slice(3)),ddLista[o.dataset.i]); } });
document.addEventListener('keydown',e=>{ const t=e.target;
  if(e.altKey&&!e.ctrlKey&&!e.metaKey){ const m={m:'materiaali',t:'tyo',k:'kone',v:'vakio'}[(e.key||'').toLowerCase()]; if(m){ e.preventDefault(); lisaa(m); return; } }
  if(t.dataset&&t.dataset.combo){ if(e.key==='ArrowDown'){ e.preventDefault(); ddIdx=Math.min(ddIdx+1,ddLista.length-1); avaaDd(t); } else if(e.key==='ArrowUp'){ e.preventDefault(); ddIdx=Math.max(ddIdx-1,0); avaaDd(t); }
    else if(e.key==='Enter'&&ddLista[ddIdx]){ e.preventDefault(); valitse(rivi(t.dataset.id),ddLista[ddIdx]); } else if(e.key==='Escape'){ t.blur(); } return; }
  if(e.key==='Enter'&&t.tagName==='INPUT'&&t.type==='text'){ e.preventDefault(); const all=[...document.querySelectorAll('#kortti input[type=text]:not([disabled]), #kortti select:not([disabled])')]; const n=all[all.indexOf(t)+1]; if(n){ n.focus(); if(n.select) n.select(); } } });
document.addEventListener('click',e=>{ const t=e.target.closest('button'); if(!t||!D) return; const d=t.dataset, r=d.id?rivi(d.id):null;
  if(d.lisaa){ lisaa(d.lisaa); }
  else if(d.tila&&r){ if(d.tila==='maara'&&r.tila==='mitat'){ const mk=menekki(r,D); if(mk.q&&!mk.osto) r.maara=nS(mk.q); } r.tila=d.tila; r.osto=false; r.kokolevyt=false; piirra(r.id,'.r2 input.n'); muuttui(); }
  else if(d.aikatila&&r){ if(r.aikatila!==d.aikatila){ const muunna=v=>{ const n=num(v); if(n===null) return ''; return d.aikatila==='h'?nS(r4(n/60)):nS(Math.round(n*60*100)/100); }; r.aika=muunna(r.aika); r.toteuma=muunna(r.toteuma); r.aikatila=d.aikatila; } piirra(r.id,'.r2 input.n'); muuttui(); }
  else if(d.kasin&&r){ r.kasin=d.kasin==='1'; if(r.kasin&&!r.aikatila){ r.aikatila='min'; r.aika=''; } r.toteuma=''; piirra(r.id,'.r2 input.n'); muuttui(true); }
  else if(d.min&&r){ r.aika=d.min; piirra(r.id,'.r2 input.n'); muuttui(); }
  else if(d.auki&&r){ r.auki=!r.auki; piirra(r.id,r.auki?'.lisat input[type=text]':null); }
  else if(d.kopio&&r){ const i=S.rivit.indexOf(r), k=Object.assign({},r,{id:uid(),db:null,lukittu:false}); if(k.tyyppi==='kone'&&k.linkki&&!k.kasin){ k.kasin=true; k.aikatila='min'; k.aika=''; } S.rivit.splice(i+1,0,k); piirra(k.id,'.main input, .main select'); muuttui(true); }
  else if(d.pois&&r){ poistetut.add(r.id); S.rivit.filter(x=>x.tyyppi==='kone'&&x.linkki===r.id).forEach(x=>poistetut.add(x.id)); S.rivit=S.rivit.filter(x=>x!==r&&!(x.tyyppi==='kone'&&x.linkki===r.id)); piirra(); muuttui(true); }
  else if(d.nakyma){ S.nakyma=d.nakyma; piirra(); }
  else if(d.perus){ S.perus=d.perus; hintaDirty=true; piirra(); muuttui(); }
  else if(d.erittely){ S.erittely=d.erittely; document.querySelectorAll('[data-erittely]').forEach(b=>b.classList.toggle('on',b.dataset.erittely===S.erittely)); }
  else if(t.id==='kayta'){ S.tarjous=fmt(window.__R.hinta,2); $('#tarjous').value=S.tarjous; hintaDirty=true; laske(); muuttui(); }
  else if(t.id==='pyorista'){ const b=num(S.tarjous)??window.__R.hinta; S.tarjous=fmt(Math.ceil(b/5-1e-9)*5,2); $('#tarjous').value=S.tarjous; hintaDirty=true; laske(); muuttui(); }
  else if(t.id==='kopioi'){ A.updateModel({teksti:tarjousteksti()}); setTimeout(()=>A.triggerEvent('onKopioi'),150); }
  else if(t.id==='avaa'){ A.triggerEvent('onAvaa'); } });

