 </div></div>`; }
function malli(m){
  if(!m) return; let d=m.d; if(typeof d==='string'){ try{ d=JSON.parse(d); }catch(e){ d=null; } }
  const tid=m.tid||'';
  if(m.virhe&&m.virhe!==viimVirhe){ viimVirhe=m.virhe; if(saving){ saving=false; asetaTila('virhe'); } }
  if(!tid){ $('#rivit').innerHTML='<div class="tyhja">Työtä ei ole valittu.</div>'; return; }
  if(!d||d.tid!==tid){ if(lataaPyydetty!==tid){ lataaPyydetty=tid; asetaTila('ladataan'); A.triggerEvent('onLataa'); } return; }
  if(S.tid===tid&&S.haettu===d.haettu) return;
  const taysi=S.tid!==tid; S.tid=tid; S.haettu=d.haettu; lataaPyydetty=null;
  if(taysi){ editSeq=saveSeq=savedSeq=0; saving=false; clearTimeout(saveTimer); }
  const olisaving=saving; if(saving){ saving=false; savedSeq=saveSeq; if(editSeq===savedSeq){ poistetut.clear(); hintaDirty=false; } }
  const rakenne=lataa(d,taysi);
  if(rakenne) piirra(); else laske();
  asetaTila(taysi?'':(editSeq===savedSeq?(olisaving?'tallennettu':''):'muutoksia'));
}
runko();
A.onReady(()=>{ malli(A.model); A.onModelChange(m=>malli(m)); });
